"""
    this function will convert bytes to MB.... GB... etc
    """
def convert_bytes(num: Any) -> object {
    step_unit = 1000.0;
    results = [];
    for x in ['bytes', 'KB', 'MB', 'GB', 'TB'] {
        results.append(("%3.2f %s" % (num, x)));
        num /= step_unit;
    }
    return results;
}

"""A more conventional recursive function (not a recursive generator)"""
def count_paths_recursive(graph: Any, node_val: Any, target: Any) -> object {
    if (node_val >= target) {
        return 1;
    }
    total = 0;
    for next_node in graph[node_val] {
        total += count_paths_recursive(graph, next_node, target);
    }
    return total;
}

