"""Transform stream name string to dictionary"""
def stream_name_to_dict(stream_name: Any, separator: Any = '-') -> object {
    catalog_name = None;
    schema_name = None;
    table_name = stream_name;
    s_parts = stream_name.split(separator);
    if (len(s_parts) == 2) {
        schema_name = s_parts[0];
        table_name = s_parts[1];
    }
    if (len(s_parts) > 2) {
        catalog_name = s_parts[0];
        schema_name = s_parts[1];
        table_name = '_'.join(s_parts[2:]);
    }
    return {
        'catalog_name': catalog_name,
        'schema_name': schema_name,
        'table_name': table_name
    };
}

"""
    Generate a PEP386  compliant version

    Stolen from django.utils.version.get_version

    :param v tuple: A five part tuple indicating the version
    :returns str: Compliant version
    """
def get_version(v: Any) -> object {
    assert isinstance(v, `tuple);
    assert (len(v) == 5);
    assert (v[3] in ('alpha', 'beta', 'rc', 'final'));
    parts = 2 if (v[2] == 0) else 3;
    main = '.'.join(str(i) for i in v[:parts]);
    sub = '';
    if (v[3] != 'final') {
        mapping = {'alpha': 'a', 'beta': 'b', 'rc': 'c'};
        sub = mapping[v[3]] + str(v[4]);
    }
    return str((main + sub));
}

